   195	// loadWorktreeIncludePatterns reads .worktreeinclude from root. A missing
   196	// file means nothing gets copied. Lines are gitignore-style patterns; blank
   197	// lines and #-comments are skipped.
   198	func loadWorktreeIncludePatterns(root string) ([]string, error) {
   199		data, err := os.ReadFile(filepath.Join(root, worktreeIncludeFile)) //nolint:gosec // path derived from repo root
   200		if errors.Is(err, fs.ErrNotExist) {
   201			return nil, nil
   202		}
   203		if err != nil {
   204			return nil, fmt.Errorf("failed to read %s: %w", worktreeIncludeFile, err)
   205		}
   206		var patterns []string
   207		for raw := range strings.SplitSeq(string(data), "\n") {
   208			line := strings.TrimRight(raw, "\r")
   209			if strings.TrimSpace(line) == "" || strings.HasPrefix(line, "#") {
   210				continue
   211			}
   212			patterns = append(patterns, line)
   213		}
   214		return patterns, nil
   215	}
