   235	func matchIncludePatterns(patterns, files []string) []string {
   236		ps := make([]gitignore.Pattern, 0, len(patterns))
   237		for _, pattern := range patterns {
   238			ps = append(ps, gitignore.ParsePattern(pattern, nil))
   239		}
   240		matcher := gitignore.NewMatcher(ps)
   241		included := make([]string, 0, len(files))
   242		for _, file := range files {
   243			rel, ok := cleanRelativeIncludeFile(file)
   244			if !ok || isManagedTrailWorktreePath(rel) || !matcher.Match(strings.Split(filepath.ToSlash(rel), "/"), false) {
   245				continue
   246			}
   247			included = append(included, rel)
   248		}
   249		return included
   250	}
