   252	// isManagedTrailWorktreePath excludes paths under .entire/worktrees from the
   253	// copy candidates: once the ignore rule ships, sibling trail worktrees' own
   254	// ignored files (e.g. their .env) appear in `git ls-files --ignored` at the
   255	// main root and would otherwise be copied into every new worktree.
   256	func isManagedTrailWorktreePath(rel string) bool {
   257		slash := filepath.ToSlash(rel)
   258		return slash == trailWorktreesRelDir || strings.HasPrefix(slash, trailWorktreesRelDir+"/")
