   284		if err != nil {
   285			return err //nolint:wrapcheck // open error is sufficient for caller context
   286		}
   287		defer in.Close()
   288		openedInfo, err := in.Stat()
   289		if err != nil {
   290			return err //nolint:wrapcheck // stat error is sufficient for caller context
   291		}
