   296			return err //nolint:wrapcheck // mkdir error is sufficient for caller context
   297		}
   298		out, err := destRoot.OpenFile(rel, os.O_WRONLY|os.O_CREATE|os.O_EXCL, srcInfo.Mode().Perm())
   299		if err != nil {
   300			return err //nolint:wrapcheck // openfile error is sufficient for caller context
   301		}
