   318	// checkoutTrailWorktree checks branch out into a managed worktree under
   319	// <main-root>/.entire/worktrees instead of switching the current checkout.
   320	// The final output line is a shell-safe `cd '<path>'` hint.
   321	func checkoutTrailWorktree(ctx context.Context, w, errW io.Writer, branch string, force bool, trailNumber int) error {
