   326			return fmt.Errorf("trail for branch %q has no number yet; cannot check out into a worktree", branch)
   327		}
   328		if err := ValidateBranchName(ctx, branch); err != nil {
   329			return err
   330		}
   331	
   332		root, err := trailWorktreeBaseRoot(ctx)
   333		if err != nil {
   334			return fmt.Errorf("failed to find main worktree root: %w", err)
   335		}
