   337		match, found, err := findWorktreeForBranch(ctx, branch, root)
   338		if err != nil {
   339			return err
   340		}
   341		if found {
   342			switch _, statErr := os.Stat(match.path); {
   343			case statErr == nil:
   344				if !match.managed {
   345					return fmt.Errorf("branch %q is already checked out at %s", branch, match.path)
   346				}
   347				fmt.Fprintf(w, "Worktree already exists at %s\n", match.path)
   348				fmt.Fprintf(w, "cd %s\n", shellQuote(match.path))
   349				return nil
   350			case errors.Is(statErr, fs.ErrNotExist):
   351				// The worktree directory was deleted by hand, leaving a stale git
   352				// registration that blocks a fresh `git worktree add` for the
   353				// branch. Cleaning it up is the user's call.
   354				return fmt.Errorf("branch %q is registered to a missing worktree at %s; run 'git worktree prune' to clear it", branch, match.path)
