   360		proceed, err := ensureTrailWorktreeBranchAvailable(ctx, w, branch, force)
   361		if err != nil {
   362			return err
   363		}
   364		if !proceed {
   365			fmt.Fprintf(w, "Checkout of branch %s cancelled.\n", branch)
   366			return nil
   367		}
