   399	// findWorktreeForBranch returns the worktree that has branch checked out,
   400	// with found reporting whether any worktree does.
   401	func findWorktreeForBranch(ctx context.Context, branch, root string) (match trailWorktreeMatch, found bool, err error) {
   402		cmd := exec.CommandContext(ctx, "git", "worktree", "list", "--porcelain")
   403		output, err := cmd.Output()
   404		if err != nil {
   405			return trailWorktreeMatch{}, false, fmt.Errorf("failed to list worktrees: %w", err)
