   455	// fetchTrailWorktreeBranch fetches origin's branch directly into refs/heads
   456	// so `git worktree add` can check it out without touching the current
   457	// checkout.
   458	func fetchTrailWorktreeBranch(ctx context.Context, branch string) error {
   459		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
   460		defer cancel()
   461	
   462		refSpec := fmt.Sprintf("refs/heads/%s:refs/heads/%s", branch, branch)
   463		// NoFilter: the worktree checkout needs full branch content; a partial
   464		// clone would leave blobs missing.
   465		output, err := remote.Fetch(ctx, remote.FetchOptions{
   466			Remote:   "origin",
   467			RefSpecs: []string{refSpec},
   468			NoFilter: true,
   469		})
   470		if err != nil {
   471			if errors.Is(ctx.Err(), context.DeadlineExceeded) {
   472				return errors.New("fetch timed out after 2 minutes")
   473			}
   474			return fmt.Errorf("failed to fetch branch from origin: %s: %w", strings.TrimSpace(string(output)), err)
   475		}
   476		return nil
   477	}

