   176	// runTrailShow shows one trail, defaulting to the current branch's trail.
   177	func runTrailShow(ctx context.Context, w, errW io.Writer, insecureHTTP bool, selector, repoOverride, branchOverride string) error {
   178		return runAuthenticatedTrailAPI(ctx, errW, insecureHTTP, repoOverride, func(ctx context.Context, client *api.Client) error {
   179			forge, owner, repo, err := resolveTrailRepoOrRemote(ctx, repoOverride)
   180			if err != nil {
   181				return err
   182			}
   183	
   184			found, err := resolveTrailBySelector(ctx, client, forge, owner, repo, selector, branchOverride)
   185			if err != nil {
   186				return err
   187			}
   188	
   189			// Enrich the list result with the detail endpoint, which carries the
   190			// rendered description (trail.body_document.text_snapshot) the list
   191			// omits, and surface a browser URL. The detail fetch is best-effort:
   192			// the core metadata already came from the list, so a detail failure
   193			// falls back to the list body with a warning rather than failing.
   194			m := found.ToMetadata()
   195			webURL := trailDisplayURL(*found, forge, owner, repo)
   196			// Seed the description from the list body so a failed (or skipped)
   197			// detail fetch still shows something; a successful detail fetch
   198			// supersedes it with the richer body_document text below.
   199			bodyText := found.Body
   200			descriptionLoaded := strings.TrimSpace(found.Body) != ""
   201			if found.Number > 0 {
   202				if bt, derr := fetchTrailDescription(ctx, client, forge, owner, repo, found.Number); derr == nil {
   203					// A successful fetch means we authoritatively consulted the
   204					// description, but it only supersedes the seeded list body when
   205					// it actually carries text: an older/partial server that omits
   206					// body_document returns "" here and must not blank out a list
   207					// body that is present.
   208					descriptionLoaded = true
   209					if strings.TrimSpace(bt) != "" {
   210						bodyText = bt
   211					}
   212				} else {
   213					// Best-effort: warn but still render metadata + URL (and the
   214					// list body) rather than failing the whole command.
   215					fmt.Fprintf(errW, "Warning: could not load trail description: %v\n", derr)
   216				}
   217			}
   218			printTrailDetails(w, m, webURL, trailDescriptionForDisplay(bodyText, descriptionLoaded))
   219			return nil
   220		})
   221	}
   222	
   223	// resolveTrailBySelector resolves a trail by an optional selector (trail
   224	// number, id, or branch). An empty selector falls back to the current branch's
   225	// trail. It returns an actionable error (never a nil trail with a nil error)
   226	// when nothing matches, so callers can rely on a non-nil result.
   227	func resolveTrailBySelector(ctx context.Context, client *api.Client, forge, owner, repo, selector, branchOverride string) (*api.TrailResource, error) {
   228		selector = strings.TrimSpace(selector)
   229		if selector == "" {
   230			branch, err := resolveTrailBranch(ctx, branchOverride)
   231			if err != nil {
   232				return nil, fmt.Errorf("no trail selector given and current branch is unknown: %w\nhint: run 'entire trail list --status any' or pass a trail number, id, or branch", err)
   233			}
   234			found, err := findTrailByBranch(ctx, client, forge, owner, repo, branch)
   235			if err != nil {
   236				return nil, err
   237			}
   238			if found == nil {
   239				return nil, fmt.Errorf("no trail found for current branch %q\nhint: run 'entire trail create' or 'entire trail list --status any'", branch)
   240			}
   241			return found, nil
   242		}
   243		found, err := findTrailBySelector(ctx, client, forge, owner, repo, selector)
   244		if err != nil {
   245			return nil, err
   246		}
   247		if found == nil {
   248			return nil, fmt.Errorf("no trail %q found in %s/%s/%s (run 'entire trail list --status any')", selector, forge, owner, repo)
   249		}
   250		return found, nil
   251	}
