   253	func printTrailDetails(w io.Writer, m *trail.Metadata, webURL, bodyText string) {
   254		fmt.Fprintf(w, "Trail: %s\n", m.Title)
   255		if m.Number > 0 {
   256			fmt.Fprintf(w, "  Number:  %d\n", m.Number)
   257		}
   258		if !m.TrailID.IsEmpty() {
   259			fmt.Fprintf(w, "  ID:      %s\n", m.TrailID)
   260		}
   261		fmt.Fprintf(w, "  Branch:  %s\n", m.Branch)
   262		fmt.Fprintf(w, "  Base:    %s\n", m.Base)
   263		fmt.Fprintf(w, "  Status:  %s\n", m.Status)
   264		fmt.Fprintf(w, "  Author:  %s\n", m.AuthorLogin())
   265		if strings.TrimSpace(m.Phase) != "" {
   266			fmt.Fprintf(w, "  Phase:   %s\n", trailPhaseDisplay(m.Phase))
   267		}
   268		if webURL != "" {
   269			fmt.Fprintf(w, "  URL:     %s\n", webURL)
   270		}
   271		if len(m.Labels) > 0 {
   272			fmt.Fprintf(w, "  Labels:  %s\n", strings.Join(m.Labels, ", "))
   273		}
   274		if len(m.Assignees) > 0 {
   275			fmt.Fprintf(w, "  Assignees: %s\n", strings.Join(m.Assignees, ", "))
   276		}
   277		fmt.Fprintf(w, "  Created: %s\n", m.CreatedAt.Format("2006-01-02T15:04:05Z07:00"))
   278		fmt.Fprintf(w, "  Updated: %s\n", m.UpdatedAt.Format("2006-01-02T15:04:05Z07:00"))
   279		if strings.TrimSpace(bodyText) != "" {
   280			fmt.Fprintf(w, "\nDescription:\n%s\n", bodyText)
