   289	// trailDescriptionForDisplay returns the text `trail show` renders for the
   290	// description: the body when present; the placeholder when it loaded but is
   291	// empty; or "" when it couldn't be loaded (the caller has already warned).
   292	func trailDescriptionForDisplay(bodyText string, loaded bool) string {
   293		if strings.TrimSpace(bodyText) != "" {
