   339	// fetchTrailDescription fetches a trail's rendered description text
   340	// (`trail.body_document.text_snapshot`), which the list endpoint omits, by
   341	// integer number. It returns only the description — the list result already
   342	// supplies the metadata — and decodes only the fields it needs, so it is
   343	// unaffected by the shape of sibling fields like `checkpoints`/`thread`.
   344	func fetchTrailDescription(ctx context.Context, client *api.Client, forge, owner, repo string, number int) (string, error) {
   345		resp, err := client.Get(ctx, trailNumberPath(forge, owner, repo, number))
   346		if err != nil {
   347			return "", fmt.Errorf("failed to fetch trail detail: %w", err)
   348		}
   349		defer resp.Body.Close()
   350		if err := checkTrailResponse(resp); err != nil {
   351			return "", err
   352		}
   353		var detail struct {
   354			Trail api.TrailResource `json:"trail"`
   355		}
   356		if err := api.DecodeJSON(resp, &detail); err != nil {
   357			return "", fmt.Errorf("failed to decode trail detail: %w", err)
   358		}
   359		if detail.Trail.BodyDocument == nil {
   360			return "", nil
   361		}
   362		return strings.TrimSpace(detail.Trail.BodyDocument.TextSnapshot), nil
   363	}
